import React, { useState } from "react";
import Navbar from "./components/NavbarPlayer";
import "./components/navbar.css";

const PlayerSearch = () => {
  const [searchTerm, setSearchTerm] = useState("");
  const [searchResults, setSearchResults] = useState([]);
  const [errorMessage, setErrorMessage] = useState("");

  const fetchDesignersByName = async (name) => {
    try {
      const response = await fetch(`http://localhost:8080/search-designers?name=${name}`);
      if (response.ok) {
        const data = await response.json();
        return data.designers; // فرض کنید سرور لیستی از طراحان را در designers بازمی‌گرداند
      } else {
        console.error("Failed to fetch search results.");
        return [];
      }
    } catch (error) {
      console.error("Error fetching search results:", error);
      return [];
    }
  };

  const handleSearchClick = async () => {
    if (searchTerm.trim()) {
      const results = await fetchDesignersByName(searchTerm);
      if (results.length > 0) {
        setSearchResults(results);
        setErrorMessage("");
      } else {
        setSearchResults([]);
        setErrorMessage("طراحی با این نام پیدا نشد.");
      }
    } else {
      setSearchResults([]);
      setErrorMessage("لطفاً یک نام وارد کنید.");
    }
  };

  const handleFollow = (designerId) => {
    // API call to follow a designer
    fetch(`http://localhost:8080/follow/${designerId}`, { method: "POST" })
      .then((response) => {
        if (response.ok) {
          alert("طراح با موفقیت دنبال شد.");
        } else {
          alert("خطا در دنبال کردن طراح.");
        }
      })
      .catch((error) => {
        console.error("Error following designer:", error);
      });
  };

  return (
    <div className="main-container">
      <Navbar />
      <h1>جستجوی طراحان</h1>
      <input
        type="text"
        placeholder="نام طراح را وارد کنید..."
        value={searchTerm}
        onChange={(e) => setSearchTerm(e.target.value)}
        className="search-input"
      />
      <button onClick={handleSearchClick} className="search-button">
        جستجو
      </button>
      {errorMessage && <p className="error-message">{errorMessage}</p>}
      <div className="results-container">
        {searchResults.map((designer) => (
          <div key={designer.id} className="designer-card">
            <p>{designer.name}</p>
            <button onClick={() => handleFollow(designer.id)}>دنبال کردن</button>
          </div>
        ))}
      </div>
    </div>
  );
};

export default PlayerSearch;
